// === CADUCEU - SISTEMA 1 (sem formatação de DATA DE VENCIMENTO) ===

const map = {
  'CPF/CNPJ (A)': 'Cliente.NúmeroDoDocumento',
  'NOME (B)': 'Cliente.Nome',
  'VAZIA (C)': '',
  'CPF/CNPJ (D)': 'Cliente.NúmeroDoDocumento',
  'VAZIA (E)': '',
  'VAZIA (F)': '',
  'VAZIA (G)': '',
  'VAZIA (H)': '',
  'VAZIA (I)': '',
  'VAZIA (J)': '',
  'CELULAR (K)': 'Cliente.Telefones',
  'VAZIA (L)': '',
  'RESPONSÁVEL (M)': 'Cliente.Nome',
  'COBRANÇA FATURA (N)': 'Cobrança.IdDaFatura',
  'DATA DE VENCIMENTO (O)': 'Cobrança.DataDeVencimento',
  'VALOR (P)': 'Cobrança.Valor',
  'EMAIL (Q)': 'Cliente.EMail'
};

// 🔧 Funções auxiliares
const normalize = str => str ? str.toString().trim().toLowerCase() : '';
const limparEmail = email => email ? email.toString().replace(/['"]/g, '').trim() : '';

const formatarCPF = valor => {
  if (!valor) return '="00000000000"';
  const num = valor.toString().replace(/\D/g, '').trim();
  return `="${num.padStart(11, '0').slice(-11)}"`;
};

const formatarValor = valor => {
  if (!valor) return '="0,00"';
  let numStr = valor.toString().replace(/[^\d,.-]/g, '').trim().replace(',', '.');
  const num = parseFloat(numStr);
  if (isNaN(num)) return '="0,00"';
  return `="${num.toFixed(2).replace('.', ',')}"`;
};

// 🗓️ Converte número serial (tipo 45483.999...) → yyyymmdd
const formatarDataSerialExcel = valor => {
  const num = parseFloat(valor);
  if (isNaN(num)) return '';

  // Excel base: 30/12/1899
  const baseDate = new Date(1899, 11, 30);
  baseDate.setDate(baseDate.getDate() + Math.floor(num));

  const yyyy = baseDate.getFullYear();
  const mm = String(baseDate.getMonth() + 1).padStart(2, '0');
  const dd = String(baseDate.getDate()).padStart(2, '0');

  return `${yyyy}${mm}${dd}`;
};

const formatarCelular = valor => {
  if (!valor) return '';
  let num = valor.toString().replace(/\D/g, '').trim();
  if (num.startsWith('55') && num.length > 11) {
    num = num.slice(2);
  }
  return num ? `="${num}"` : '';
};

const formatarNumeroGrande = valor => {
  if (!valor) return '';
  const num = valor.toString().replace(/\D/g, '').trim();
  return num ? `="${num}"` : '';
};

const usarPrimeiraLinhaComoCabecalho = data => {
  if (!Array.isArray(data) || data.length < 2) return [];
  const headerRow = data[0];
  const conteudo = data.slice(1);
  return conteudo.map(row => {
    const obj = {};
    headerRow.forEach((col, i) => {
      obj[col?.toString().trim()] = row[i];
    });
    return obj;
  });
};

// 🔍 Lê dados do nó anterior
let inputData = $input.all().map(i => i.json);
if (inputData.length === 1 && Array.isArray(inputData[0].data)) {
  inputData = usarPrimeiraLinhaComoCabecalho(inputData[0].data);
}

// 🧱 Processamento principal
const output = inputData.map(row => {
  const novo = {};

  for (const [saida, entrada] of Object.entries(map)) {
    let valor = '';
    if (entrada) valor = row[entrada] ?? '';

    switch (saida) {
      case 'CPF/CNPJ (A)':
      case 'CPF/CNPJ (D)':
        valor = formatarCPF(valor);
        break;
      case 'CELULAR (K)':
        valor = formatarCelular(valor);
        break;
      case 'COBRANÇA FATURA (N)':
        valor = formatarNumeroGrande(valor);
        break;
      // ❌ NÃO FORMATAR A DATA
      case 'DATA DE VENCIMENTO (O)':
        valor = formatarDataSerialExcel(valor);
        break;
      case 'VALOR (P)':
        valor = formatarValor(valor);
        break;
      case 'EMAIL (Q)':
        valor = limparEmail(valor);
        break;
    }

    novo[saida] = valor;
  }

  for (const [saida] of Object.entries(map)) {
    if (saida.includes('VAZIA') && !(saida in novo)) novo[saida] = '';
  }

  return { json: novo };
});

const resultadoFinal = output.filter(item => {
  const str = Object.values(item.json || {})
    .join('')
    .replace(/[^A-Za-z0-9]/g, '')
    .trim();
  return str.length > 0;
});

return resultadoFinal;
